"""CARLA-lazy original capture of a source-surveyed two-way to one-way left turn."""

import json
from math import hypot
from pathlib import Path
from threading import Condition
from time import monotonic

from turn_native_plan import control_step, seal_route_source, verify_loaded_map
from turn_source_recorder import SourceRecorder


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class FourCameraCapture:
    def __init__(self, world, carla_module, ego, on_frame, *, overview_mount_z_m=8.):
        if not 6. <= overview_mount_z_m <= 12.:
            raise ValueError("Invalid engineering overview mount height")
        self.condition = Condition()
        self.frames = {name: set() for name in CAMERAS}
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (location, rotation, size, fov) in CAMERAS.items():
                if name == "overview":
                    location = (location[0], location[1], overview_mount_z_m)
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", .05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(carla_module.Location(*location),
                                                   carla_module.Rotation(*rotation))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image, on_frame))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image, on_frame):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original camera dimensions changed")
                on_frame(name, image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Original camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original camera frames")

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()


def _footprint(ego):
    corners = []
    for vertex in ego.bounding_box.get_world_vertices(ego.get_transform()):
        xy = [float(vertex.x), float(vertex.y)]
        if not any(hypot(xy[0]-old[0], xy[1]-old[1]) < 1e-4 for old in corners):
            corners.append(xy)
    if len(corners) != 4:
        raise ValueError("Original Native body footprint incomplete")
    return corners


def _phase(world_map, carla_module, ego, approach_road, departure_road):
    waypoint = world_map.get_waypoint(ego.get_location(), project_to_road=True,
                                      lane_type=carla_module.LaneType.Driving)
    if waypoint is None:
        raise ValueError("Original ego left surveyed driving route")
    if waypoint.is_junction:
        return "entry"
    if waypoint.road_id == approach_road:
        return "approach"
    if waypoint.road_id == departure_road:
        return "departure"
    raise ValueError("Original ego entered an unselected road")


def drive(world, carla_module, ego, plan, route, cameras, recorder, *, frames=160):
    settings = world.get_settings()
    if not settings.synchronous_mode or abs(float(settings.fixed_delta_seconds) - .05) > 1e-6:
        raise ValueError("Original turn capture requires synchronized 20 Hz world")
    targets = plan["targets_xy_m"]
    observed = []
    world_map = world.get_map()

    def record_tick():
        if len(observed) >= frames:
            raise ValueError("Turn exceeded fixed capture duration")
        frame = world.tick()
        cameras.wait_for_frame(frame)
        snapshot = world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError("Original Native snapshot frame mismatch")
        recorder.record_body({"frame": frame, "time_s": float(snapshot.timestamp.elapsed_seconds),
                              "phase": _phase(world_map, carla_module, ego, route[0].road_id,
                                              route[-1].road_id),
                              "actor_id": ego.id, "body_corners_xy_m": _footprint(ego)})
        observed.append(frame)

    for target in targets[1:]:
        reached = False
        for _ in range(120):
            transform = ego.get_transform()
            location = transform.location
            position = float(location.x), float(location.y)
            if hypot(target[0]-position[0], target[1]-position[1]) < .8:
                reached = True
                break
            forward = transform.get_forward_vector()
            velocity = ego.get_velocity()
            controls = control_step(position, (float(forward.x), float(forward.y)),
                                    (float(velocity.x), float(velocity.y)), target,
                                    target_speed_mps=plan.get("target_speed_mps", 4.))
            ego.apply_control(carla_module.VehicleControl(**controls))
            record_tick()
        if not reached:
            location = ego.get_transform().location
            reached = hypot(target[0]-location.x, target[1]-location.y) < .8
        if not reached:
            ego.apply_control(carla_module.VehicleControl(throttle=0., steer=0., brake=1.))
            raise ValueError("Ego did not reach surveyed turn target in tick budget")
    ego.apply_control(carla_module.VehicleControl(throttle=0., steer=0., brake=1.))
    while len(observed) < frames:
        record_tick()
    cameras.verify(observed)
    return {"frames": observed, "targets_reached": len(targets)-1,
            "physical_turn_claimed": False}


def run(plan, output, host="127.0.0.1", port=2000):
    import carla  # Native dependency is intentionally lazy.

    output = Path(output)
    output.mkdir(parents=True, exist_ok=True)
    if any((output / (name + ".mkv")).exists() for name in CAMERAS):
        raise ValueError("Retain prior Native original cameras")
    client = carla.Client(host, int(port))
    client.set_timeout(30.)
    world = client.get_world()
    world_map = world.get_map()
    route = verify_loaded_map(world_map, plan, carla.LaneType.Driving)
    old_settings = world.get_settings()
    old_sync = old_settings.synchronous_mode
    old_delta = old_settings.fixed_delta_seconds
    ego = None
    recorder = None
    cameras = None
    try:
        settings = world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = .05
        world.apply_settings(settings)
        spawn = route[0].transform
        offset = plan.get("spawn_height_offset_m", .5)
        if not .3 <= offset <= 1.:
            raise ValueError("Invalid engineering spawn height")
        spawn.location.z += offset
        ego = world.try_spawn_actor(world.get_blueprint_library().find("vehicle.tesla.model3"), spawn)
        if ego is None:
            raise ValueError("Native left-turn ego spawn failed")
        recorder = SourceRecorder(output, {name: spec[2] for name, spec in CAMERAS.items()})
        seal_route_source(world_map, plan, carla.LaneType.Driving, output)
        cameras = FourCameraCapture(world, carla, ego, recorder.on_frame,
                                    overview_mount_z_m=plan.get("overview_mount_z_m", 8.))
        outcome = drive(world, carla, ego, plan, route, cameras, recorder)
        recorder.seal()
        (output / "native-turn-result.json").write_text(json.dumps(outcome, indent=2) + "\n")
        return outcome
    finally:
        try:
            if cameras is not None:
                cameras.close()
        finally:
            try:
                if recorder is not None:
                    recorder.close()
            finally:
                try:
                    if ego is not None:
                        ego.destroy()
                finally:
                    old_settings.synchronous_mode = old_sync
                    old_settings.fixed_delta_seconds = old_delta
                    world.apply_settings(old_settings)

"""Retain four original Native cameras and frame-joined turn-body observations."""

import json
from pathlib import Path
import subprocess
from threading import Lock


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


class SourceRecorder:
    def __init__(self, output, camera_sizes, fps=20):
        if fps != 20 or set(camera_sizes) != set(CAMERAS):
            raise ValueError("Four named 20 Hz original cameras required")
        self.output = Path(output)
        self.output.mkdir(parents=True, exist_ok=True)
        self.sizes = camera_sizes
        self.lock = Lock()
        self.encoders = {}
        self.camera_frames = {name: [] for name in CAMERAS}
        self.body = []
        self.closed = False
        try:
            for name in CAMERAS:
                width, height = camera_sizes[name]
                if type(width) is not int or type(height) is not int or min(width, height) < 1:
                    raise ValueError("Invalid original camera dimensions")
                stderr = (self.output / (name + "-encoder.log")).open("wb")
                command = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                           "-f", "rawvideo", "-pixel_format", "bgra",
                           "-video_size", f"{width}x{height}", "-framerate", "20",
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-threads", "1",
                           str(self.output / (name + ".mkv"))]
                try:
                    process = subprocess.Popen(command, stdin=subprocess.PIPE,
                                               stdout=subprocess.DEVNULL, stderr=stderr)
                except BaseException:
                    stderr.close()
                    raise
                self.encoders[name] = process, stderr
        except BaseException:
            self.close()
            raise

    def on_frame(self, name, image):
        with self.lock:
            if self.closed or name not in self.encoders:
                raise ValueError("Original camera recorder closed or unknown")
            width, height = self.sizes[name]
            if (image.width, image.height) != (width, height):
                raise ValueError("Original camera size changed")
            raw = bytes(image.raw_data)
            if len(raw) != width * height * 4:
                raise ValueError("Original camera payload incomplete")
            rows = self.camera_frames[name]
            if rows and image.frame <= rows[-1]["frame"]:
                raise ValueError("Original camera frames out of order")
            process = self.encoders[name][0]
            if process.poll() is not None:
                raise ValueError("Original camera encoder exited early")
            process.stdin.write(raw)
            rows.append({"frame": int(image.frame), "time_s": float(image.timestamp)})

    def record_body(self, row):
        with self.lock:
            if self.closed or not all(key in row for key in
                                      ("frame", "time_s", "phase", "actor_id", "body_corners_xy_m")):
                raise ValueError("Original turn body sample incomplete")
            if row["phase"] not in ("approach", "entry", "departure"):
                raise ValueError("Unknown original road phase")
            if self.body and row["frame"] <= self.body[-1]["frame"]:
                raise ValueError("Original body frames out of order")
            if len(row["body_corners_xy_m"]) != 4:
                raise ValueError("Original body needs four footprint corners")
            self.body.append(row)

    def close(self):
        if self.closed:
            return
        self.closed = True
        failures = []
        for name, (process, stderr) in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:
                    process.stdin.close()
                if process.wait(timeout=30):
                    failures.append(name)
            finally:
                stderr.close()
        if failures:
            raise ValueError("Original camera encoder failed: " + ", ".join(failures))

    def seal(self):
        self.close()
        frames = [row["frame"] for row in self.body]
        if not frames or set(row["phase"] for row in self.body) != {"approach", "entry", "departure"}:
            raise ValueError("Original turn phases missing")
        if not (self.output / "route_survey_capture_receipt.json").is_file():
            raise ValueError("Verified original Native route survey missing")
        for name in CAMERAS:
            rows = self.camera_frames[name]
            video = self.output / (name + ".mkv")
            if not video.is_file() or not video.stat().st_size:
                raise ValueError("Original camera video missing: " + name)
            if [row["frame"] for row in rows] != frames:
                raise ValueError("Original camera/body frame join differs: " + name)
            if any(abs(a["time_s"] - b["time_s"]) > .05 for a, b in zip(rows, self.body)):
                raise ValueError("Original camera/body time join differs: " + name)
        with (self.output / "body_corners_original.jsonl").open("x") as stream:
            for row in self.body:
                stream.write(json.dumps(row, allow_nan=False) + "\n")
        with (self.output / "trace.jsonl").open("x") as stream:
            for row in self.body:
                corners = row["body_corners_xy_m"]
                centre = [sum(corner[axis] for corner in corners) / 4 for axis in (0, 1)]
                stream.write(json.dumps({"frame": row["frame"], "time_s": row["time_s"],
                                         "position_m": centre}, allow_nan=False) + "\n")
        with (self.output / "video_frames.jsonl").open("x") as stream:
            for index, row in enumerate(self.body):
                stream.write(json.dumps({"video_frame": index, "carla_frame": row["frame"],
                                         "native_frame": row["frame"], "time_s": row["time_s"]},
                                        allow_nan=False) + "\n")
        for name in CAMERAS:
            with (self.output / (name + "-frames.jsonl")).open("x") as stream:
                for index, row in enumerate(self.camera_frames[name]):
                    stream.write(json.dumps({"video_frame": index, "native_frame": row["frame"],
                                             "time_s": row["time_s"]}, allow_nan=False) + "\n")
        return {"frames": len(frames), "original_cameras": list(CAMERAS),
                "original_body": "body_corners_original.jsonl",
                "original_route": "route_survey_original.json",
                "frame_map": "video_frames.jsonl"}

"""Source-bound Native route validation for the two-way to one-way left turn.

The catalog's generic ``road`` label does not establish an intersection.  A
survey identifies the actual XODR lanes; this module checks those lanes again
against the loaded Native map before a construction may use them.
"""

import hashlib
import json
from math import cos, hypot, isfinite, pi, sin
from pathlib import Path


def _point(value):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError("Survey needs two-dimensional coordinates")
    point = tuple(float(component) for component in value)
    if not all(isfinite(component) for component in point):
        raise ValueError("Survey coordinates must be finite")
    return point


def load_survey(path, expected_sha256):
    path = Path(path)
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("Route survey source hash differs")
    survey = json.loads(raw)
    if survey.get("provenance_kind") != "native_xodr_survey":
        raise ValueError("Route survey needs Native XODR provenance")
    if not survey.get("map_name") or survey.get("intersection_kind") != "public_highway_non_alley":
        raise ValueError("Survey does not identify the qualifying intersection")
    if survey.get("approach_directions") != 2 or survey.get("destination_directions") != 1:
        raise ValueError("Survey needs two-way approach and one-way exit")
    route = survey.get("waypoints")
    if not isinstance(route, list) or len(route) < 3:
        raise ValueError("Survey needs approach, junction and exit waypoints")
    for item in route:
        if not all(key in item for key in ("road_id", "lane_id", "s", "xy_m")):
            raise ValueError("Survey waypoint is incomplete")
        _point(item["xy_m"])
    for key in ("approach_centerline_xy_m", "destination_left_curb_xy_m"):
        line = survey.get(key)
        if not isinstance(line, list) or len(line) != 2:
            raise ValueError("Survey lacks a controlling road line")
        a, b = map(_point, line)
        if hypot(a[0] - b[0], a[1] - b[1]) <= 0:
            raise ValueError("Survey road line is degenerate")
    entry = _point(survey.get("intersection_entry_xy_m"))
    a, b = map(_point, survey["approach_centerline_xy_m"])
    cross = (b[0] - a[0]) * (entry[1] - a[1]) - (b[1] - a[1]) * (entry[0] - a[0])
    if abs(cross) > 1e-4:
        raise ValueError("Intersection entry is off the approach centerline")
    return survey


def verify_native_route(world_map, survey, driving_lane_type):
    """Return checked Native waypoints; no route or direction is inferred."""
    if world_map.name != survey["map_name"]:
        raise ValueError("Loaded Native map differs from survey")
    waypoints = []
    for item in survey["waypoints"]:
        waypoint = world_map.get_waypoint_xodr(item["road_id"], item["lane_id"], item["s"])
        if waypoint is None or waypoint.lane_type != driving_lane_type:
            raise ValueError("Surveyed driving lane is unavailable")
        actual = waypoint.transform.location
        expected = _point(item["xy_m"])
        if hypot(actual.x - expected[0], actual.y - expected[1]) > 0.5:
            raise ValueError("Native waypoint differs from source coordinates")
        waypoints.append(waypoint)
    if not any(waypoint.is_junction for waypoint in waypoints[1:-1]):
        raise ValueError("Surveyed route has no interior Native junction")
    if waypoints[0].road_id == waypoints[-1].road_id:
        raise ValueError("Turn does not enter a different road")
    _verify_road_directions(world_map, waypoints, driving_lane_type)
    return waypoints


def _heading(waypoint):
    angle = waypoint.transform.rotation.yaw * pi / 180
    return cos(angle), sin(angle)


def _dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def _verify_road_directions(world_map, route, driving_lane_type):
    """Inventory Native driving lanes on each selected road by heading.

    The map's lane inventory is a physical topology check. Public access and
    applicable highway operation still need original source review.
    """
    inventory = [waypoint for waypoint in world_map.generate_waypoints(2.0)
                 if waypoint.lane_type == driving_lane_type and not waypoint.is_junction]
    approach_road = route[0].road_id
    destination_road = route[-1].road_id
    approach = [waypoint for waypoint in inventory if waypoint.road_id == approach_road]
    destination = [waypoint for waypoint in inventory if waypoint.road_id == destination_road]
    if not approach or not destination:
        raise ValueError("Native direction inventory lacks selected roads")
    incoming = _heading(route[0])
    outgoing = _heading(route[-1])
    if not any(_dot(_heading(wp), incoming) > .7 for wp in approach):
        raise ValueError("Native approach has no incoming driving direction")
    if not any(_dot(_heading(wp), incoming) < -.7 for wp in approach):
        raise ValueError("Native approach lacks opposing driving direction")
    if not any(_dot(_heading(wp), outgoing) > .7 for wp in destination):
        raise ValueError("Native exit has no departing driving direction")
    if any(_dot(_heading(wp), outgoing) < -.7 for wp in destination):
        raise ValueError("Native exit has opposing driving direction")
    if any(abs(_dot(_heading(wp), outgoing)) <= .7 for wp in destination):
        raise ValueError("Native exit has ambiguous driving direction")

"""Measure original vehicle corners against surveyed turn geometry.

Distances describe source geometry.  They do not decide what is nearest or
as close as practicable under NRS 484B.400(3).
"""

from math import hypot, isfinite


def point(value):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError("Expected original two-dimensional point")
    result = tuple(float(v) for v in value)
    if not all(isfinite(v) for v in result):
        raise ValueError("Nonfinite original point")
    return result


def directed_line(value):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError("Expected surveyed directed line")
    start, end = map(point, value)
    dx, dy = end[0] - start[0], end[1] - start[1]
    length = hypot(dx, dy)
    if length <= 0:
        raise ValueError("Degenerate surveyed line")
    return start, (dx / length, dy / length), length


def signed_offset(p, origin, direction):
    return direction[0] * (p[1] - origin[1]) - direction[1] * (p[0] - origin[0])


def distance_to_segment(p, origin, direction, length):
    along = (p[0] - origin[0]) * direction[0] + (p[1] - origin[1]) * direction[1]
    along = max(0, min(length, along))
    return hypot(p[0] - origin[0] - along * direction[0],
                 p[1] - origin[1] - along * direction[1])


def measure_frame(body, survey):
    """Preserve per-corner measurements and the original frame identity."""
    phase = body.get("phase")
    if phase not in ("approach", "entry", "departure"):
        raise ValueError("Original body phase is unknown")
    frame = body.get("frame")
    if not isinstance(frame, int) or isinstance(frame, bool) or frame < 0:
        raise ValueError("Original body frame is invalid")
    corners = [point(v) for v in body.get("body_corners_xy_m", [])]
    if len(corners) != 4 or len(set(corners)) != 4:
        raise ValueError("Need four distinct original body corners")
    center, center_direction, center_length = directed_line(survey["approach_centerline_xy_m"])
    curb, curb_direction, curb_length = directed_line(survey["destination_left_curb_xy_m"])
    center_offsets = [signed_offset(v, center, center_direction) for v in corners]
    curb_distances = [distance_to_segment(v, curb, curb_direction, curb_length) for v in corners]
    return {
        "frame": frame,
        "phase": phase,
        "approach_centerline_signed_corner_offsets_m": center_offsets,
        "all_corners_right_of_approach_centerline": max(center_offsets) < 0,
        "departure_left_curb_corner_distances_m": curb_distances,
        "farthest_body_corner_from_departure_left_curb_m": max(curb_distances),
    }
